import{_ as t,o as e,c as r,a3 as d}from"./chunks/framework.WFmvnizL.js";const p=JSON.parse('{"title":"哪吒监控 V2 版本与兼容性","description":"解释哪吒监控 V2 产品代际、Dashboard 与 Agent 独立版本、/api/v1 接口路径、旧 V0/V1 文档和升级兼容性的区别。","frontmatter":{"title":"哪吒监控 V2 版本与兼容性","description":"解释哪吒监控 V2 产品代际、Dashboard 与 Agent 独立版本、/api/v1 接口路径、旧 V0/V1 文档和升级兼容性的区别。","outline":"deep"},"headers":[],"relativePath":"guide/version-compatibility.md","filePath":"guide/version-compatibility.md","lastUpdated":1792674226000}'),o={name:"guide/version-compatibility.md"};function i(l,a,h,n,s,b){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="哪吒监控-v2-版本与兼容性" tabindex="-1">哪吒监控 V2 版本与兼容性 <a class="header-anchor" href="#哪吒监控-v2-版本与兼容性" aria-label="Permalink to &quot;哪吒监控 V2 版本与兼容性&quot;">​</a></h1><p>当前文档面向 <strong>哪吒监控 V2</strong>。理解“产品代际”“组件版本”和“接口版本”的区别，可以避免把 <code>/api/v1</code>、旧教程或某个组件标签误认为当前产品仍是 V1。</p><h2 id="四种版本标识分别表示什么" tabindex="-1">四种版本标识分别表示什么？ <a class="header-anchor" href="#四种版本标识分别表示什么" aria-label="Permalink to &quot;四种版本标识分别表示什么？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标识</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td>产品代际</td><td>哪吒监控 V2</td><td>当前整体产品与文档代际</td></tr><tr><td>Dashboard 版本</td><td><code>v2.x.y</code></td><td><a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard 仓库</a>独立发布的服务端版本</td></tr><tr><td>Agent 版本</td><td><code>v2.x.y</code></td><td><a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent 仓库</a>独立发布的客户端版本，版本号不要求与 Dashboard 完全相同</td></tr><tr><td>API 路径版本</td><td><code>/api/v1/...</code></td><td>REST API 路由命名，用于接口兼容；不代表产品代际</td></tr></tbody></table><p>因此，当前使用 V2 Dashboard 时看到 <code>/api/v1/server</code> 是正常的。不要把 API 路径批量替换成 <code>/api/v2</code>；只有官方代码和 API 文档明确新增路径时才能使用新地址。</p><h2 id="dashboard-与-agent-是否必须同版本" tabindex="-1">Dashboard 与 Agent 是否必须同版本？ <a class="header-anchor" href="#dashboard-与-agent-是否必须同版本" aria-label="Permalink to &quot;Dashboard 与 Agent 是否必须同版本？&quot;">​</a></h2><p>两者独立发布，不要求补丁版本完全一致，但不应据此假设任意跨版本组合都兼容。推荐做法是：</p><ol><li>生产环境使用两个仓库各自的稳定 Release。</li><li>升级前分别阅读 Dashboard 和 Agent 的 Release Notes。</li><li>先备份 Dashboard 数据和配置。</li><li>小规模节点先升级并观察连接、状态上报、服务检查和远程操作。</li><li>再逐步升级其余 Agent，避免一次性失去全部节点可见性。</li></ol><p>如果 Dashboard 页面要求强制更新 Agent，或日志出现协议、认证或字段错误，应以当前 Release 说明和 Issue 为准，不要只比较版本号字符串。</p><h2 id="组件职责与功能边界" tabindex="-1">组件职责与功能边界 <a class="header-anchor" href="#组件职责与功能边界" aria-label="Permalink to &quot;组件职责与功能边界&quot;">​</a></h2><p>管理前端与用户前端独立发布。官方 Dashboard 发布包中的前端由构建时的模板清单决定；第三方主题不一定实现相同功能。本指南直接描述当前稳定版的行为。</p><table tabindex="0"><thead><tr><th>功能</th><th>当前行为与边界</th></tr></thead><tbody><tr><td>移动端终端</td><td>管理前端提供按键操作栏和剪贴板按钮；Agent 执行终端输入、尺寸调整与颜色显示</td></tr><tr><td>GPU 显存</td><td>Agent 上报逐卡显存，Dashboard 转发，默认用户前端展示；当前仅 Linux NVIDIA 支持显存采集</td></tr><tr><td>JWT 会话跨 IP 使用</td><td><code>allow_jwt_ip_change</code> 默认关闭；当前管理前端无开关，可通过配置文件或设置 API 修改</td></tr><tr><td>在线历史</td><td>Dashboard 在数据库中保存在线会话，不依赖 TSDB；默认用户前端提供“在线”标签，默认查询 1 天</td></tr><tr><td>在线统计范围</td><td><code>online_stats_days</code> 默认 7 天，范围 7–3650 天，同时控制保留与最大查询窗口</td></tr></tbody></table><p>在线历史从收到状态上报开始积累，不回填此前未记录的时段。默认用户前端提供 1/7/30 天选项，API 最大窗口与后台保留范围一致；各组件的独立版本号不要求相同。</p><h2 id="v0、v1-和-v2-文档如何处理" tabindex="-1">V0、V1 和 V2 文档如何处理？ <a class="header-anchor" href="#v0、v1-和-v2-文档如何处理" aria-label="Permalink to &quot;V0、V1 和 V2 文档如何处理？&quot;">​</a></h2><ul><li><strong>V2</strong>：当前安装、配置、API 与排障页面的默认目标。</li><li><strong>V1</strong>：历史产品代际；当前安装和使用应按 V2 文档操作，不套用旧版配置或命令。</li><li><strong>V0</strong>：旧配置格式、数据库和登录流程可能与当前版本不兼容。保留旧 URL 的页面只用于解释历史，不应直接用于新部署。</li><li><strong>社区项目名称中的 V1</strong>：如果上游项目仓库或名称明确写有 V1，文档会保留原名并标记为第三方或历史项目，而不会把它改成并不存在的 V2 兼容版本。</li></ul><h2 id="常见的-版本看起来不一致" tabindex="-1">常见的“版本看起来不一致” <a class="header-anchor" href="#常见的-版本看起来不一致" aria-label="Permalink to &quot;常见的“版本看起来不一致”&quot;">​</a></h2><h3 id="为什么-api-仍然是-api-v1" tabindex="-1">为什么 API 仍然是 <code>/api/v1</code>？ <a class="header-anchor" href="#为什么-api-仍然是-api-v1" aria-label="Permalink to &quot;为什么 API 仍然是 `/api/v1`？&quot;">​</a></h3><p>接口版本和产品代际是独立的。当前 <a href="/guide/api.html">API 文档</a>仍以实际 Dashboard 路由为准。</p><h3 id="当前文档采用什么行为口径" tabindex="-1">当前文档采用什么行为口径？ <a class="header-anchor" href="#当前文档采用什么行为口径" aria-label="Permalink to &quot;当前文档采用什么行为口径？&quot;">​</a></h3><p>安装、配置、API 和排障页面直接描述当前稳定版行为。例如，Web 与 Agent 通信使用统一端口，本地账号支持绑定 OAuth2。历史发布记录用于审查与追溯，不作为当前使用步骤的前置条件。</p><h3 id="为什么社区项目页面仍然写-v1" tabindex="-1">为什么社区项目页面仍然写 V1？ <a class="header-anchor" href="#为什么社区项目页面仍然写-v1" aria-label="Permalink to &quot;为什么社区项目页面仍然写 V1？&quot;">​</a></h3><p>社区页面记录第三方项目。名称或兼容范围由其维护者决定；官方文档不能在没有上游证据时宣称它支持 V2。部署前必须检查项目最近提交、Release 和 Issue。</p><h2 id="升级前检查清单" tabindex="-1">升级前检查清单 <a class="header-anchor" href="#升级前检查清单" aria-label="Permalink to &quot;升级前检查清单&quot;">​</a></h2><ul><li>查看 <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard Releases</a>和 <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent Releases</a>。</li><li>备份 <code>/opt/nezha</code> 或实际映射的数据、配置和 TSDB 目录。</li><li>记录当前 Dashboard 与 Agent 版本、安装方式、域名和反向代理配置。</li><li>确认数据库迁移、配置字段变更和废弃功能说明。</li><li>测试登录、Agent 上线、WebSocket、gRPC、通知和授权运维功能。</li><li>不要用旧版 Docker Compose、配置样例或二进制覆盖当前部署。</li></ul><p>安装与更新流程见<a href="/guide/dashboard.html">安装 Dashboard</a>、<a href="/guide/agent.html">安装 Agent</a>和<a href="/guide/q5.html">备份与恢复</a>。</p>',25)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
